#!/usr/bin/env node
/**
 * Read-only verification of the ACTUAL active Caddy JSON. DO NOT reload.
 * Current Live source was generated by an independently verified operator;
 * the later marketing preview route was injected via Caddy admin.
 * Any other semantic change from the last verified source blocks recovery.
 *
 * This is a reconciliation AUDIT, not authorisation to deploy, reload,
 * replace host bind sources, admit all tenants or bypass protected reviews.
 */
import {createHash} from 'node:crypto'
import {execFileSync} from 'node:child_process'
import {verifyLiveGatewayRuntimeProvenance} from '../../services/api/src/releaseGatewayProvenance.js'
const docker=(...a)=>execFileSync('docker',a,{encoding:'utf8',maxBuffer:5000000,timeout:30000})
const stable=v=>Array.isArray(v)?v.map(stable):v&&typeof v==='object'
 ?Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])])):v
const sha=v=>createHash('sha256').update(typeof v==='string'?v:JSON.stringify(stable(v))).digest('hex')
const key=r=>r.match?.[0]?.host?.join(',')||'<catch-all>'
const adapterPath='/tmp/staff-verified-upgrade-1792092421202.Caddyfile'
const expectedPreview='marketing-preview.hi5central.com'
if(process.argv.length!==2)throw Error('This verifier is read-only and takes no arguments.')
let report={type:'LIVE_CADDY_RUNTIME_PROVENANCE_V1',readOnly:true,verified:false,
 gatewayMutated:false,blockers:[]}
try{
 const source=docker('exec','hi5central-web','cat',adapterPath)
 const host=docker('run','--rm','--network','none','--mount',
  'type=bind,source=/opt/hi5central/deployment/Caddyfile,target=/gateway/Caddyfile,readonly',
  'busybox:1.36','cat','/gateway/Caddyfile')
 const mounted=docker('exec','hi5central-web','cat','/etc/caddy/Caddyfile')
 const provenance=JSON.parse(docker('exec','hi5central-web','caddy','adapt',
  '--config',adapterPath,'--adapter','caddyfile'))
 const active=JSON.parse(docker('exec','hi5central-web','wget','-q','-O','-',
  'http://127.0.0.1:2019/config/'))
 const proof=verifyLiveGatewayRuntimeProvenance({lastVerified:provenance,active})
 if(!proof.verified)report.blockers.push(proof.reason)
 report={...report,verified:report.blockers.length===0,
  sources:{hostSha256:sha(host),mountedSha256:sha(mounted),
    lastVerifiedSourceSha256:sha(source),activeJsonSha256:sha(active)},
  compared:{preservedExistingHostRules:proof.verifiedExistingRoutes,
    exactHostRuleMatches:proof.verifiedExistingRoutes,
    onlyAdditionalActiveHost:proof.previewPreserved?'marketing-preview.hi5central.com':null,
    activeRouteCount:proof.activeRoutes},
  stillRequires:{sourceReconciliation:sha(host)!==sha(mounted)||sha(mounted)!==sha(source),
    liveApiSameOriginChecks:true,managedUatAndNonEntitledRmmHostBoundaries:true,
    independentlyReviewedHostExecutor:true}}
}catch(error){report.blockers.push(String(error.message||error).slice(0,180))}
console.log(JSON.stringify(report,null,2))
if(!report.verified)process.exitCode=2
